DROP TABLE IF EXISTS `audit_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `audit_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `actor_id` bigint(20) unsigned DEFAULT NULL,
  `actor_username` varchar(100) DEFAULT NULL,
  `action` varchar(80) NOT NULL,
  `entity_type` varchar(100) NOT NULL,
  `entity_id` bigint(20) unsigned DEFAULT NULL,
  `scope_unit_id` bigint(20) unsigned DEFAULT NULL,
  `old_value` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`old_value`)),
  `new_value` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`new_value`)),
  `reason` varchar(1000) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `request_id` varchar(100) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `actor_role` varchar(150) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_audit_logs_entity_time` (`entity_type`,`entity_id`,`created_at`),
  KEY `idx_audit_logs_actor_time` (`actor_id`,`created_at`),
  KEY `idx_audit_logs_action_time` (`action`,`created_at`),
  KEY `idx_audit_logs_scope_time` (`scope_unit_id`,`created_at`),
  CONSTRAINT `fk_audit_logs_actor` FOREIGN KEY (`actor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_audit_logs_scope_unit` FOREIGN KEY (`scope_unit_id`) REFERENCES `organizational_units` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1208 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Append-only generic audit log; not a replacement for domain-specific history';
/*!40101 SET character_set_client = @saved_cs_client */;

