DROP TABLE IF EXISTS `course_offerings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `course_offerings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `registration_period_id` bigint(20) unsigned NOT NULL,
  `course_version_id` bigint(20) unsigned NOT NULL,
  `class_code` varchar(50) NOT NULL,
  `capacity` int(10) unsigned NOT NULL,
  `minimum_capacity` int(10) unsigned DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'PLANNED',
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_course_offerings_period_class` (`registration_period_id`,`class_code`),
  KEY `idx_course_offerings_course_period` (`course_version_id`,`registration_period_id`),
  KEY `idx_course_offerings_status` (`status`),
  KEY `fk_course_offerings_created_by` (`created_by`),
  CONSTRAINT `fk_course_offerings_course_version` FOREIGN KEY (`course_version_id`) REFERENCES `course_versions` (`id`),
  CONSTRAINT `fk_course_offerings_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_course_offerings_period` FOREIGN KEY (`registration_period_id`) REFERENCES `registration_periods` (`id`),
  CONSTRAINT `chk_course_offerings_capacity` CHECK (`capacity` > 0),
  CONSTRAINT `chk_course_offerings_min_capacity` CHECK (`minimum_capacity` is null or `minimum_capacity` <= `capacity`),
  CONSTRAINT `chk_course_offerings_status` CHECK (`status` in ('PLANNED','OPEN','CLOSED','CONFIRMED','CANCELLED','COMPLETED'))
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Actual course classes offered during a registration period; distinct from courses';
