--
-- Table structure for table `course_versions`
--

DROP TABLE IF EXISTS `course_versions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `course_versions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `course_id` bigint(20) unsigned NOT NULL,
  `version_no` int(10) unsigned NOT NULL,
  `course_name` varchar(255) NOT NULL,
  `english_name` varchar(255) DEFAULT NULL,
  `credits` decimal(5,2) NOT NULL,
  `theory_hours` smallint(5) unsigned NOT NULL DEFAULT 0,
  `practice_hours` smallint(5) unsigned NOT NULL DEFAULT 0,
  `description` text DEFAULT NULL,
  `search_text` varchar(600) DEFAULT NULL,
  `effective_from` date NOT NULL,
  `effective_to` date DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `active_key` bigint(20) unsigned GENERATED ALWAYS AS (case when `status` = 'ACTIVE' then `course_id` end) STORED,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_course_versions_course_version` (`course_id`,`version_no`),
  UNIQUE KEY `uk_course_versions_active` (`active_key`),
  KEY `idx_course_versions_course_effective` (`course_id`,`effective_from`),
  KEY `idx_course_versions_status` (`status`),
  KEY `fk_course_versions_created_by` (`created_by`),
  FULLTEXT KEY `ft_course_versions_search` (`search_text`),
  CONSTRAINT `fk_course_versions_course` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`),
  CONSTRAINT `fk_course_versions_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_course_versions_credits` CHECK (`credits` > 0),
  CONSTRAINT `chk_course_versions_dates` CHECK (`effective_to` is null or `effective_to` >= `effective_from`),
  CONSTRAINT `chk_course_versions_status` CHECK (`status` in ('DRAFT','ACTIVE','RETIRED'))
) ENGINE=InnoDB AUTO_INCREMENT=74 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Versioned course name, credits, hours and description; published curricula reference this table';
/*!40101 SET character_set_client = @saved_cs_client */;

