CREATE TABLE `courses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `owning_unit_id` bigint(20) unsigned NOT NULL,
  `course_code` varchar(50) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  `retired_at` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_courses_course_code` (`course_code`),
  KEY `idx_courses_owning_unit` (`owning_unit_id`),
  KEY `idx_courses_status` (`status`),
  CONSTRAINT `fk_courses_owning_unit` FOREIGN KEY (`owning_unit_id`) REFERENCES `organizational_units` (`id`),
  CONSTRAINT `chk_courses_status` CHECK (`status` in ('ACTIVE','INACTIVE','RETIRED'))
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Stable course identity. Mutable academic attributes live in course_versions';
