DROP TABLE IF EXISTS `program_version_tracks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `program_version_tracks` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `program_version_id` bigint(20) unsigned NOT NULL,
  `study_track_id` bigint(20) unsigned DEFAULT NULL,
  `track_code_snapshot` varchar(50) NOT NULL,
  `track_name_snapshot` varchar(150) NOT NULL,
  `required_total_credits` decimal(6,2) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_program_version_tracks_code` (`program_version_id`,`track_code_snapshot`),
  KEY `idx_program_version_tracks_track` (`study_track_id`),
  KEY `idx_program_version_tracks_version` (`program_version_id`),
  CONSTRAINT `fk_program_version_tracks_track` FOREIGN KEY (`study_track_id`) REFERENCES `study_tracks` (`id`),
  CONSTRAINT `fk_program_version_tracks_version` FOREIGN KEY (`program_version_id`) REFERENCES `program_versions` (`id`),
  CONSTRAINT `chk_program_version_tracks_credits` CHECK (`required_total_credits` >= 0),
  CONSTRAINT `chk_program_version_tracks_status` CHECK (`status` in ('ACTIVE','INACTIVE'))
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Version-specific study tracks. study_track_id may be NULL for a general/default track';
